    'notif.reason.alertNamed': 'Cette notification vous a été envoyée car vous avez activé l\'alerte « {alert} » pour la catégorie {category}{price}.',
    'notif.reason.alertGeneric': 'Cette notification vous a été envoyée car vous avez activé une alerte pour la catégorie {category}{price}.',
