window.UI_TRANSLATIONS = UI_TRANSLATIONS;

// Récupère une clé de traduction pour la langue courante, avec repli sur le
// français si la clé est absente (évite un texte vide en cas d'oubli).
function t(key, langue) {
  const dict = UI_TRANSLATIONS[langue] || UI_TRANSLATIONS.fr;
  return dict[key] ?? UI_TRANSLATIONS.fr[key] ?? key;
}
window.t = t;

// ─── CATÉGORIES (libellé traduit d'une catégorie Firestore) ───
// L'identité d'une catégorie = sa valeur en base (t.category), jamais traduite.
// categoryId() en dérive un id stable (« Design 3D » → « design-3d », même
// règle que slugify() d'app.js et que les URLs /categorie/{langue}/{slug}/).
// translateCategory() ne fait QUE fournir le texte visible :
//   1. langue demandée  2. français  3. valeur brute (catégorie inconnue).
// Une catégorie ajoutée dans Firebase s'affiche donc d'office (valeur brute)
// sans aucune liste à maintenir ; ajouter 'cat.<id>' ici la traduit.
function categoryId(value) {
  return String(value == null ? '' : value).toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
}
// Nouvelle nomenclature des catégories : plusieurs anciennes valeurs Firestore
// (ex. Audio, Musique) et les nouveaux noms pointent vers UN SEUL nom canonique,
// afin que les tuiles, filtres et libellés fusionnent sans toucher à la base.
const CATEGORY_CANONICAL = {
  'audio': "Audio & Musique", 'musique': "Audio & Musique", 'audio-musique': "Audio & Musique",
  'recherche': "Assistants IA et recherche", 'assistants-ia-et-recherche': "Assistants IA et recherche",
  'video': "Vidéo et animation", 'video-et-animation': "Vidéo et animation",
  'image': "Images et design", 'images': "Images et design", 'design': "Images et design",
  'design-3d': "Images et design", 'images-et-design': "Images et design",
  'marketing': "Rédaction et marketing", 'redaction-et-marketing': "Rédaction et marketing",
  'code': "Programmation et création d'applications",
  'programmation-et-creation-d-applications': "Programmation et création d'applications",
  'productivite': "Productivité, études et traduction", 'traduction': "Productivité, études et traduction",
  'education': "Productivité, études et traduction",
  'productivite-etudes-et-traduction': "Productivité, études et traduction"
};
function canonicalCategory(value) {
  if (value == null || value === '') return value;
  return CATEGORY_CANONICAL[categoryId(value)] || value;
}
window.canonicalCategory = canonicalCategory;
function translateCategory(value, langue) {
  if (value == null || value === '') return '';
  const lang = langue || (typeof detecterLangue === 'function' ? detecterLangue() : 'fr');
  // Libellé saisi dans l'admin (collection Firestore « categories », chargée par app.js) : prioritaire.
  const saisi = window.CATEGORY_LABELS && window.CATEGORY_LABELS[canonicalCategory(value)];
  if (saisi && saisi[lang] && saisi[lang].name) return saisi[lang].name;
  const key = 'cat.' + categoryId(canonicalCategory(value));
  const dict = UI_TRANSLATIONS[lang] || UI_TRANSLATIONS.fr;
  return dict[key] ?? UI_TRANSLATIONS.fr[key] ?? String(value);
}
window.categoryId = categoryId;
window.translateCategory = translateCategory;

// Applique les traductions statiques à tout le DOM courant : texte simple
// (data-i18n), HTML avec balises (data-i18n-html) et placeholders
// d'input (data-i18n-placeholder). À appeler au chargement initial de
// chaque page et à chaque changement de langue.
function appliquerTraductionsStatiques(langue) {
  document.querySelectorAll('[data-i18n]').forEach(el => {
    const key = el.getAttribute('data-i18n');
    el.textContent = t(key, langue);
  });
  document.querySelectorAll('[data-i18n-html]').forEach(el => {
    const key = el.getAttribute('data-i18n-html');
    el.innerHTML = t(key, langue);
  });
  document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
    const key = el.getAttribute('data-i18n-placeholder');
    el.setAttribute('placeholder', t(key, langue));
  });
  document.querySelectorAll('[data-i18n-title]').forEach(el => {
    const key = el.getAttribute('data-i18n-title');
    el.setAttribute('title', t(key, langue));
  });
  document.querySelectorAll('[data-i18n-aria-label]').forEach(el => {
    const key = el.getAttribute('data-i18n-aria-label');
    el.setAttribute('aria-label', t(key, langue));
  });
  document.querySelectorAll('[data-i18n-tooltip]').forEach(el => {
    const key = el.getAttribute('data-i18n-tooltip');
    el.setAttribute('data-tooltip', t(key, langue));
  });
  document.querySelectorAll('.lang-btn').forEach(btn => {
    btn.classList.toggle('active', btn.dataset.lang === langue);
  });
  // Une page statique garde sa langue déclarée (hreflang, SEO).
  if (!document.documentElement.hasAttribute('data-static-lang')) {
    document.documentElement.lang = langue;
  }
}
window.appliquerTraductionsStatiques = appliquerTraductionsStatiques;

// Fonction générique de changement de langue, réutilisable par n'importe
// quelle page (boutons nav, paramètres profil...). Persiste le choix dans
// localStorage (donc partagé par toutes les pages du site) et réapplique
// immédiatement les traductions statiques sur la page courante.
//
// Les pages qui ont du contenu dynamique en plus (ex: index.html avec
// renderTools()/renderBlog()/renderGallery(), ou profil.html avec ses
// propres listes Firestore) doivent définir window.onLangueChange = fn
// AVANT que ce script s'exécute, ou simplement rappeler leurs propres
// fonctions de rendu après avoir appelé changerLangueGlobale().
function changerLangueGlobale(code) {
  if (!LANGUES_SUPPORTEES.includes(code)) return code;
  localStorage.setItem(LS_LANG_KEY, code);
  appliquerTraductionsStatiques(code);
  if (typeof window.onLangueChange === 'function') {
    window.onLangueChange(code);
  }
  return code;
}
window.changerLangueGlobale = changerLangueGlobale;

// Applique automatiquement la langue détectée dès que ce script se charge,
// AVANT même DOMContentLoaded si possible, pour éviter un flash de contenu
// en français sur une page qu'un visiteur EN/ES a déjà configurée. On
// réapplique quand même une fois le DOM prêt, au cas où des éléments
// data-i18n sont ajoutés dynamiquement après coup (ex: contenu Firestore
// avec sa propre logique, ou fragments injectés en JS).
document.addEventListener('DOMContentLoaded', () => {
  appliquerTraductionsStatiques(detecterLangue());
});
